"""Source/native JSONL I/O bindings for Java-generated byte fixtures."""
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "reference/upstream"))
from tokeneconomizer.trace import jsonl
if "--native" in sys.argv:
    from native_plugin import invoke

for line in sys.stdin:
    request = json.loads(line)
    result = invoke("trace.jsonl." + request["method"], dict(path=request["path"])) if "--native" in sys.argv else list(getattr(jsonl, request["method"])(request["path"]))
    print(json.dumps(result, sort_keys=True, ensure_ascii=True, separators=(",", ":")), flush=True)
